// "Reading the territory": the narrative generated by the storytelling service. Each figure
// carries the colour of its scale, like the chips on the cards, and a sentence can lead the
// reader to the data behind it (the page decides where: a map indicator or a card).

import { el } from './charts.js';
import { t } from './i18n.js';

/** The fact a sentence is about: its own, or the one its caveat is attached to. */
function sentenceFact(sentence, caveats) {
  if (sentence.facts.length) return sentence.facts[0];
  const rule = sentence.caveats[0];
  return caveats.find((c) => c.rule === rule)?.fact;
}

function renderSentence(sentence, caveats, link) {
  const fact = sentenceFact(sentence, caveats);
  const title = fact && link ? link.title(fact) : null;
  const node = el('span', {
    class: `narrative-sentence${title ? ' is-linkable' : ''}`,
    dataset: { fact: fact || '' },
    tabindex: title ? 0 : null,
    role: title ? 'button' : null,
    title,
  },
    sentence.segments.map((segment) => (segment.scope
      ? el('span', { class: `scope-inline scope-${segment.scope}`, title: t(`narrative.scope.${segment.scope}`), text: segment.text })
      : segment.text)),
    ' ');
  if (title) {
    node.addEventListener('click', (event) => {
      if (event.target.closest('a')) return;
      link.select(fact);
    });
    node.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        link.select(fact);
      }
    });
  }
  return node;
}

function provenance(body) {
  const planned = body.facts.filter((f) => f.planned);
  const rows = planned.map((f) => el('tr', {},
    el('td', { text: f.id }),
    el('td', { text: Object.entries(f.slots)
      .filter(([, slot]) => slot.scope && 'value' in slot)
      .map(([field, slot]) => `${field}: ${slot.text}`)
      .join(' · ') }),
    el('td', { class: 'numeric', text: f.importance.toFixed(2) })));
  const rules = body.caveats.map((c) => el('li', {
    text: t('narrative.rule', { rule: c.rule, note: c.note, effect: t(`narrative.effect.${c.effect}`), fact: c.fact }),
  }));
  return el('details', { class: 'narrative-how' },
    el('summary', { text: t('narrative.how') }),
    el('p', { class: 'hint', text: t('narrative.method', { version: body.version }) }),
    el('table', { class: 'narrative-facts' },
      el('thead', {}, el('tr', {},
        el('th', { text: t('narrative.fact') }), el('th', { text: t('narrative.values') }), el('th', { text: t('narrative.importance') }))),
      el('tbody', {}, rows)),
    rules.length ? el('ul', { class: 'narrative-rules' }, rules) : null,
    el('p', { class: 'hint', text: body.verified ? t('narrative.verified') : t('narrative.unverified') }));
}

/**
 * @param {{title: (fact: string) => string|null, select: (fact: string) => void}} [link]
 *   where a sentence about `fact` leads; a null title leaves the sentence plain
 */
export function renderNarrative(container, body, link) {
  const hasLead = body.plan[0].length > 0;
  container.replaceChildren(
    el('h3', { class: 'card-title', text: t('narrative.title') }),
    el('div', { class: 'narrative-layout' },
      el('div', { class: 'narrative-body' },
        ...body.paragraphs.map((paragraph, i) => el('p', { class: `narrative-text${hasLead && i === 0 ? ' is-lead' : ''}` },
          paragraph.map((sentence) => renderSentence(sentence, body.caveats, link)))),
        el('p', { class: 'hint', text: `${t('narrative.auto')} ${link ? t('narrative.clickHint') : ''}`.trim() }),
        provenance(body)),
      scaleKey(body)));
  container.hidden = false;
}

const SCALES = ['radius', 'catchment', 'district', 'city', 'municipality', 'region'];

/** Key to the scale colours used in this text, so the colour is never the only cue. */
function scaleKey(body) {
  const used = new Set(body.paragraphs.flat().flatMap((sentence) => sentence.segments.map((segment) => segment.scope)));
  const scales = SCALES.filter((scale) => used.has(scale));
  if (!scales.length) return null;
  return el('aside', { class: 'scale-key' },
    el('h4', { text: t('narrative.scales') }),
    el('ul', {}, scales.map((scale) => el('li', {},
      el('span', { class: `scope-inline scope-${scale}`, text: t(`narrative.scaleName.${scale}`) }),
      el('span', { class: 'hint', text: t(`narrative.scaleNote.${scale}`) })))));
}

export function renderNarrativeState(container, key) {
  container.replaceChildren(
    el('h3', { class: 'card-title', text: t('narrative.title') }),
    el('p', { class: 'hint', text: t(key) }));
  container.hidden = false;
}
